const Markdoc = require('@markdoc/markdoc');
const {default: slugify}=require('@sindresorhus/slugify');
const {Config,nodes,Tag,functions}=Markdoc;
function getIdForHeading(node){if(typeof node.attributes.id==='string')return node.attributes.id;let s='';for(const child of node.walk()){if(child.type==='text'||child.type==='code')s+=child.attributes.content;}return slugify(s)}
function validateLink(node,config){return []}
const base={variables:{},functions:Object.fromEntries(Object.keys(Markdoc.functions).map(k=>[k,undefined])),validation:{validateFunctions:true},tags:{},nodes:{document:{...Markdoc.nodes.document,validate(document){const errors=[]; const seen=new Map(); for(const node of document.walk()){if(node.type==='heading'){const id=getIdForHeading(node); if(id.length===0) continue; const existing=seen.get(id); if(!existing){seen.set(id,node);continue;} const err=node=>({id:'ambiguous-heading-id',level:'error',message:`amb ${id}`,location:node.location}); if(existing!=='reported'){errors.push(err(existing)); seen.set(id,'reported')} errors.push(err(node));}} return errors;}},heading:{render:'Heading',attributes:{level:{type:Number,required:true},id:{type:String}},validate(node){const errors=[]; if(node.attributes.level===1) errors.push({message:'no h1',id:'no-h1',level:'error'}); const id=getIdForHeading(node); if(id.length===0) errors.push({id:'empty-id',level:'error',message:'empty'}); return errors;},transform(node,config){const attributes=node.transformAttributes(config); const children=node.transformChildren(config); return new Markdoc.Tag(this.render,{...attributes,id:getIdForHeading(node)},children)}}}};
