7.   createElement: typeof createElement;
8.   Fragment: typeof Fragment;
9. }>;
10. 
11. type Component = ComponentType<unknown>;
12. 
13. function tagName(
14.   name: string,
15.   components: Record<string, Component> | ((string: string) => Component)
16. ): string | Component {
17.   return typeof name !== 'string'
18.     ? name // This can be an object, e.g. when React.forwardRef is used
19.     : name[0] !== name[0].toUpperCase()
20.     ? name
21.     : components instanceof Function
22.     ? components(name)
23.     : components[name];
24. }
25. 
26. export default function dynamic(
27.   node: RenderableTreeNodes,
28.   React: ReactShape,
29.   { components = {} } = {}
30. ) {
31.   function deepRender(value: any): any {
32.     if (value == null || typeof value !== 'object') return value;
33. 
34.     if (Array.isArray(value)) return value.map((item) => deepRender(item));
35. 
36.     if (value.$$mdtype === 'Tag') return render(value);
37. 
38.     if (typeof value !== 'object') return value;
39. 
40.     const output: Record<string, Scalar> = {};
41.     for (const [k, v] of Object.entries(value)) output[k] = deepRender(v);
42.     return output;
43.   }
44. 
45.   function render(node: RenderableTreeNodes): ReactNode {
46.     if (Array.isArray(node))
47.       return React.createElement(React.Fragment, null, ...node.map(render));
48. 
49.     if (node === null || typeof node !== 'object' || !Tag.isTag(node))
50.       return node;
51. 
52.     const {
53.       name,
54.       attributes: { class: className, ...attrs } = {},
55.       children = [],
56.     } = node;
57. 
